const SOURCE_TABLE = 'guidebook_principles';
const AGG_NODE     = 'Aggregate1';

// при Batch Size 1 в батче ровно одна строка — её id и берём
const sent = $(AGG_NODE).first().json.row_text;
const line = Array.isArray(sent) ? String(sent[0]) : String(sent);
const m = line.match(/\[id=(\d+)\]/);
if (!m) throw new Error('Нет маркера id в строке: ' + line.slice(0, 200));
const SOURCE_ID = Number(m[1]);
let raw = '';
for (const item of $input.all()) {
  try {
    const t = String(item.json.choices[0].message.content || '');
    if (t.length > raw.length) raw = t;
  } catch (e) {
    for (const v of Object.values(item.json)) {
      if (typeof v === 'string' && v.length > raw.length) raw = v;
    }
  }
}
raw = raw.replace(/<think>[\s\S]*?<\/think>/gi, '');
raw = raw.replace(/<think>[\s\S]*/gi, '');

if (!raw) throw new Error('LLM ничего не вернула');

const out = [];

function push(qt, txt, ref) {
  const t = String(txt || '').trim();
  if (t.length < 15) return;
  out.push({
    source_table:     SOURCE_TABLE,
    source_id:        SOURCE_ID,
    question_type:    ['theory','practice','case'].indexOf(qt) !== -1 ? qt : 'theory',
    question_text:    t,
    reference_answer: String(ref || '').trim(),
    status:           'draft'
  });
}

// попытка 1: разобрать как JSON
let parsed = null;
const s = raw.indexOf('{');
const e = raw.lastIndexOf('}');
if (s !== -1 && e > s) {
  const frag = raw.slice(s, e + 1);
  try { parsed = JSON.parse(frag); }
  catch (e1) {
    try { parsed = JSON.parse(frag.replace(/,\s*([}\]])/g, '$1')); }
    catch (e2) { parsed = null; }
  }
}

function eat(v, depth) {
  if (v === null) return;
  if (v === undefined) return;
  if (depth > 5) return;
  if (Array.isArray(v)) { for (const x of v) eat(x, depth + 1); return; }
  if (typeof v === 'object') {
    if (v.question_text) { push(v.question_type, v.question_text, v.reference_answer); return; }
    for (const x of Object.values(v)) eat(x, depth + 1);
  }
}
if (parsed) eat(parsed, 0);

// попытка 2: вытащить пары регулярками, если JSON битый
if (out.length === 0) {
  const qs = raw.match(/"question_text"\s*:\s*"([^"]{15,400})"/g) || [];
  const as = raw.match(/"reference_answer"\s*:\s*"([^"]{0,600})"/g) || [];
  for (let i = 0; i < qs.length; i++) {
    const q = qs[i].replace(/^"question_text"\s*:\s*"/, '').replace(/"$/, '');
    let a = '';
    if (as[i]) a = as[i].replace(/^"reference_answer"\s*:\s*"/, '').replace(/"$/, '');
    push(i === 0 ? 'theory' : 'practice', q, a);
  }
}

if (out.length === 0) {
  throw new Error('Вопросов не найдено. id=' + SOURCE_ID + '. Ответ: ' + raw.slice(0, 400));
}
return out.map(o => ({ json: o }));

